#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class ProgramVoicesTask final {
public:
 enum class Stage {PrepareRelease,EnterRelease,PrepareClear,PublishPart,ReadPart,ClearIndex,PublishIndex,ReadCount,RetainCount,RetainPart,RetainMode,SelectVoice,ReadAge,SelectAge,ReadOwner,CompareOwner,SelectOwner,MaskAge,MarkAge,RetainAge,PrepareTail,PublishAge,ReadPatch,SelectDsp,ReadMode,RetainModeValue,SelectMode,PrepareGain,PrepareCommand,WriteGain,WriteGate,ReadIndex,AdvanceIndex,WriteIndex,RestoreMode,RestorePart,RestoreCount,DecrementCount,Repeat,ClearKeys,Return,Complete};
 enum class Read {Part,Count,Age,Owner,Patch,Index};enum class Write {Part,Index,Age};enum class Child {None,Voice,Dsp,Gain,Gate,Keys};
 explicit ProgramVoicesTask(uint8_t part,bool release=true):stage_(release?Stage::PrepareRelease:Stage::PrepareClear),part_(part),release_(release){}
 Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}Child child()const{return child_;}bool awaiting()const{return child_!=Child::None;}
 bool resumeChild(uint32_t result=0){if(!awaiting())return false;if(child_==Child::Voice)voice_=result;child_=Child::None;return true;}
 uint32_t voice()const{return voice_;}uint8_t part()const{return part_;}uint32_t packedAge()const{return (uint32_t(age_)<<16)|0xffff;}
 unsigned nextClocks(const FlashCredits&c)const{if(awaiting()||complete())return 0;switch(stage_){case Stage::PrepareRelease:case Stage::PrepareTail:case Stage::PrepareGain:case Stage::PrepareCommand:return 6;case Stage::PublishPart:case Stage::PublishIndex:case Stage::WriteIndex:return 9+c.write;case Stage::ReadPart:case Stage::ReadCount:case Stage::ReadIndex:return 9+c.read;case Stage::RetainCount:case Stage::RetainPart:case Stage::RetainMode:case Stage::RetainModeValue:return c.pushWord;case Stage::ReadMode:case Stage::RestoreMode:case Stage::RestorePart:case Stage::RestoreCount:return c.popWord;case Stage::SelectVoice:case Stage::SelectDsp:case Stage::WriteGain:case Stage::WriteGate:case Stage::ClearKeys:return c.call;case Stage::ReadAge:case Stage::ReadOwner:return 12+c.read;case Stage::ReadPatch:return 15+c.read;case Stage::PublishAge:return 15+c.write;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::EnterRelease:next=Stage::PublishPart;break;case Stage::PublishPart:write(Write::Part,part_);break;case Stage::ReadPart:part_=uint8_t(read(Read::Part));break;case Stage::ClearIndex:index_=0;break;case Stage::PublishIndex:case Stage::WriteIndex:write(Write::Index,index_);break;case Stage::ReadCount:remaining_=uint8_t(read(Read::Count));break;case Stage::SelectVoice:child_=Child::Voice;break;case Stage::ReadAge:age_=uint16_t(read(Read::Age));break;case Stage::SelectAge:if(!age_)next=Stage::ReadIndex;break;case Stage::ReadOwner:owner_=uint8_t(read(Read::Owner));break;case Stage::SelectOwner:if(owner_!=part_)next=Stage::ReadIndex;break;case Stage::MaskAge:age_&=0x3fff;break;case Stage::MarkAge:age_|=1;break;case Stage::PublishAge:write(Write::Age,packedAge());break;case Stage::ReadPatch:patch_=read(Read::Patch);break;case Stage::SelectDsp:child_=Child::Dsp;break;case Stage::SelectMode:if(!release_)next=Stage::WriteGate;break;case Stage::WriteGain:child_=Child::Gain;break;case Stage::WriteGate:child_=Child::Gate;break;case Stage::ReadIndex:index_=uint8_t(read(Read::Index));break;case Stage::AdvanceIndex:++index_;break;case Stage::DecrementCount:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::RetainCount;break;case Stage::ClearKeys:child_=Child::Keys;break;default:break;}stage_=next;return cost;}
private:Stage stage_;Child child_=Child::None;uint8_t part_=0,index_=0,remaining_=0,owner_=0;bool release_=true;uint16_t age_=0;uint32_t voice_=0,patch_=0;
};
class ProgramVoiceInitTask final {
public:enum class Stage {CopyPart,Address,PrepareEnable,PublishEnable,ReadGeneration,AdvanceGeneration,PublishGeneration,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}bool resumeChild(uint32_t part){if(!waiting_)return false;waiting_=false;part_=part;return true;}uint32_t part()const{return part_;}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Address:return c.call;case Stage::PublishEnable:case Stage::PublishGeneration:return 12+c.write;case Stage::ReadGeneration:return 12+c.read;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Address:waiting_=true;break;case Stage::PublishEnable:write(false,1);break;case Stage::ReadGeneration:generation_=uint8_t(read());break;case Stage::AdvanceGeneration:generation_=uint8_t(generation_+8);break;case Stage::PublishGeneration:write(true,generation_);break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::CopyPart;bool waiting_=false;uint32_t part_=0;uint8_t generation_=0;};
class ProgramVoiceStatusTask final {
public:enum class Stage {Address,Read,Publish,ClearFraction,Send,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;switch(stage_){case Stage::Address:return 6;case Stage::Read:return 9+c.read;case Stage::Publish:return 9+c.write;case Stage::Send:return c.call;case Stage::Return:return c.ret;default:return 3;}}
 template<class R,class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,R&&read,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;switch(stage_){case Stage::Read:index_=uint8_t(read());break;case Stage::Publish:write(index_);break;case Stage::Send:waiting_=true;break;default:break;}stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Address;bool waiting_=false;uint8_t index_=0;};
class ProgramHeldKeysClearTask final {
public:enum class Stage {RetainValue,RetainPointer,Bind,Count,Publish,Decrement,Repeat,RestorePointer,RestoreValue,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned index()const{return index_;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::RetainValue:return c.pushWord;case Stage::RetainPointer:return c.pushLong;case Stage::Bind:return 9;case Stage::Count:return 6;case Stage::Publish:return 5+c.write;case Stage::RestorePointer:return c.popLong;case Stage::RestoreValue:return c.popWord;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Count:remaining_=16;break;case Stage::Publish:write(index_++,0);break;case Stage::Decrement:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::Publish;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::RetainValue;uint8_t remaining_=0,index_=0;};
}
